using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

/// <summary>
/// Server-side implementation that provides shipment data directly (no HTTP call needed).
/// In production, replace the in-memory list with EF Core queries.
/// </summary>
public class ServerShipmentService : IShipmentService
{
    private static readonly List<Shipment> Shipments =
    [
        new() { Id = 1, TrackingNumber = "TRK-100201", Origin = "New York, US", Destination = "London, UK", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(4), CustomerEmail = "alice@example.com", Description = "Electronics – 2 boxes", WeightKg = 12.5 },
        new() { Id = 2, TrackingNumber = "TRK-100202", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = ShipmentStatus.Pending, ShippedDate = DateTime.UtcNow.AddDays(-1), EstimatedDelivery = DateTime.UtcNow.AddDays(12), CustomerEmail = "bob@example.com", Description = "Textiles – 1 pallet", WeightKg = 85.0 },
        new() { Id = 3, TrackingNumber = "TRK-100203", Origin = "Berlin, DE", Destination = "Tokyo, JP", Status = ShipmentStatus.OutForDelivery, ShippedDate = DateTime.UtcNow.AddDays(-7), EstimatedDelivery = DateTime.UtcNow, CustomerEmail = "carol@example.com", Description = "Auto parts – 5 crates", WeightKg = 210.0 },
        new() { Id = 4, TrackingNumber = "TRK-100204", Origin = "São Paulo, BR", Destination = "Miami, US", Status = ShipmentStatus.Delivered, ShippedDate = DateTime.UtcNow.AddDays(-10), EstimatedDelivery = DateTime.UtcNow.AddDays(-2), CustomerEmail = "dave@example.com", Description = "Coffee beans – 3 bags", WeightKg = 45.0 },
        new() { Id = 5, TrackingNumber = "TRK-100205", Origin = "Mumbai, IN", Destination = "Dubai, AE", Status = ShipmentStatus.Delayed, ShippedDate = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow.AddDays(3), CustomerEmail = "eve@example.com", Description = "Pharmaceuticals – temperature-controlled", WeightKg = 8.2 },
        new() { Id = 6, TrackingNumber = "TRK-100206", Origin = "Sydney, AU", Destination = "Auckland, NZ", Status = ShipmentStatus.PickedUp, ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(2), CustomerEmail = "frank@example.com", Description = "Furniture – 1 sofa", WeightKg = 55.0 },
        new() { Id = 7, TrackingNumber = "TRK-100207", Origin = "Toronto, CA", Destination = "Mexico City, MX", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.UtcNow.AddDays(-2), EstimatedDelivery = DateTime.UtcNow.AddDays(5), CustomerEmail = "grace@example.com", Description = "Machine components", WeightKg = 132.0 },
        new() { Id = 8, TrackingNumber = "TRK-100208", Origin = "Paris, FR", Destination = "Lagos, NG", Status = ShipmentStatus.Returned, ShippedDate = DateTime.UtcNow.AddDays(-14), EstimatedDelivery = DateTime.UtcNow.AddDays(-5), CustomerEmail = "henry@example.com", Description = "Fashion goods – 10 cartons", WeightKg = 28.0 },
    ];

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return Task.FromResult(Shipments.ToList());
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = Shipments.FirstOrDefault(s =>
            s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task<List<Shipment>> SearchShipmentsAsync(string? statusFilter, string? destinationFilter)
    {
        var query = Shipments.AsEnumerable();

        if (!string.IsNullOrEmpty(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, true, out var status))
            query = query.Where(s => s.Status == status);

        if (!string.IsNullOrEmpty(destinationFilter))
            query = query.Where(s => s.Destination.Contains(destinationFilter, StringComparison.OrdinalIgnoreCase));

        return Task.FromResult(query.ToList());
    }

    public Task UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        var shipment = Shipments.FirstOrDefault(s => s.Id == id);
        if (shipment is not null)
            shipment.Status = newStatus;
        return Task.CompletedTask;
    }
}

