@page "/"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Your Shipment</PageTitle>

<div class="container mt-4">
    <div class="text-center mb-5">
        <h1 class="display-5">📦 Shipment Tracker</h1>
        <p class="lead text-muted">Enter your tracking number to see real-time shipment status.</p>
    </div>

    <div class="row justify-content-center">
        <div class="col-md-8 col-lg-6">
            <div class="input-group input-group-lg mb-3">
                <input type="text" class="form-control" placeholder="e.g. TRK-100201"
                       @bind="trackingNumber" @bind:event="oninput"
                       @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                    @if (isLoading)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    }
                    Track
                </button>
            </div>

            @if (searched && shipment is null)
            {
                <div class="alert alert-warning">
                    <strong>Not found.</strong> No shipment matches tracking number
                    "<strong>@searchedTrackingNumber</strong>". Please check and try again.
                </div>
            }

            @if (shipment is not null)
            {
                <div class="card shadow-sm">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@shipment.TrackingNumber</strong>
                        <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
                    </div>
                    <div class="card-body">
                        <dl class="row mb-0">
                            <dt class="col-sm-5">Description</dt>
                            <dd class="col-sm-7">@shipment.Description</dd>

                            <dt class="col-sm-5">Origin</dt>
                            <dd class="col-sm-7">@shipment.Origin</dd>

                            <dt class="col-sm-5">Destination</dt>
                            <dd class="col-sm-7">@shipment.Destination</dd>

                            <dt class="col-sm-5">Shipped</dt>
                            <dd class="col-sm-7">@shipment.ShippedDate.ToString("MMM dd, yyyy")</dd>

                            <dt class="col-sm-5">Estimated Delivery</dt>
                            <dd class="col-sm-7">
                                <strong>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</strong>
                                @if (shipment.Status != ShipmentStatus.Delivered)
                                {
                                    var daysLeft = (shipment.EstimatedDelivery.Date - DateTime.UtcNow.Date).Days;
                                    <span class="text-muted ms-1">
                                        (@(daysLeft > 0 ? $"in {daysLeft} day(s)" : daysLeft == 0 ? "today" : "overdue"))
                                    </span>
                                }
                            </dd>

                            <dt class="col-sm-5">Weight</dt>
                            <dd class="col-sm-7">@shipment.WeightKg kg</dd>
                        </dl>
                    </div>
                </div>
            }
        </div>
    </div>
</div>

@code {
    private string trackingNumber = string.Empty;
    private string searchedTrackingNumber = string.Empty;
    private Shipment? shipment;
    private bool searched;
    private bool isLoading;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber))
            return;

        isLoading = true;
        searched = false;
        shipment = null;

        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
            searchedTrackingNumber = trackingNumber.Trim();
            searched = true;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.PickedUp => "bg-secondary",
        ShipmentStatus.Pending => "bg-warning text-dark",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };
}

@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher – All Shipments</PageTitle>

<div class="container-fluid mt-4">
    <h2>📋 Shipment Dashboard</h2>
    <p class="text-muted">View and manage all shipments. Use the filters to narrow results.</p>

    <div class="row g-3 mb-4">
        <div class="col-md-4">
            <label class="form-label">Filter by status</label>
            <select class="form-select" @bind="statusFilter" @bind:after="ApplyFilters">
                <option value="">All statuses</option>
                @foreach (var s in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@s">@s</option>
                }
            </select>
        </div>
        <div class="col-md-4">
            <label class="form-label">Filter by destination</label>
            <input class="form-control" placeholder="e.g. London"
                   @bind="destinationFilter" @bind:event="oninput" @bind:after="ApplyFilters" />
        </div>
        <div class="col-md-4 d-flex align-items-end">
            <button class="btn btn-outline-secondary" @onclick="ClearFilters">Clear filters</button>
        </div>
    </div>

    @if (isLoading)
    {
        <div class="d-flex justify-content-center my-5">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else if (shipments.Count == 0)
    {
        <div class="alert alert-info">No shipments match your filters.</div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover align-middle">
                <thead class="table-dark">
                    <tr>
                        <th>Tracking #</th>
                        <th>Origin</th>
                        <th>Destination</th>
                        <th>Status</th>
                        <th>Shipped</th>
                        <th>Est. Delivery</th>
                        <th>Weight (kg)</th>
                        <th>Update Status</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var s in shipments)
                    {
                        <tr>
                            <td><strong>@s.TrackingNumber</strong></td>
                            <td>@s.Origin</td>
                            <td>@s.Destination</td>
                            <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                            <td>@s.ShippedDate.ToString("MMM dd")</td>
                            <td>@s.EstimatedDelivery.ToString("MMM dd")</td>
                            <td>@s.WeightKg</td>
                            <td>
                                <select class="form-select form-select-sm"
                                        value="@s.Status"
                                        @onchange="e => UpdateStatus(s, e)">
                                    @foreach (var st in Enum.GetValues<ShipmentStatus>())
                                    {
                                        <option value="@st" selected="@(st == s.Status)">@st</option>
                                    }
                                </select>
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
        <p class="text-muted">Showing @shipments.Count shipment(s)</p>
    }
</div>

@code {
    private List<Shipment> shipments = [];
    private string statusFilter = string.Empty;
    private string destinationFilter = string.Empty;
    private bool isLoading = true;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        shipments = await ShipmentService.GetAllShipmentsAsync();
        isLoading = false;
    }

    private async Task ApplyFilters()
    {
        isLoading = true;
        shipments = await ShipmentService.SearchShipmentsAsync(
            string.IsNullOrEmpty(statusFilter) ? null : statusFilter,
            string.IsNullOrEmpty(destinationFilter) ? null : destinationFilter);
        isLoading = false;
    }

    private async Task ClearFilters()
    {
        statusFilter = string.Empty;
        destinationFilter = string.Empty;
        await LoadShipments();
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.PickedUp => "bg-secondary",
        ShipmentStatus.Pending => "bg-warning text-dark",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };
}

