    Results.Ok(await svc.GetAllShipmentsAsync()))
    .RequireAuthorization();

shipmentApi.MapGet("/track/{trackingNumber}", async (string trackingNumber, ServerShipmentService svc) =>
{
    var shipment = await svc.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
});

shipmentApi.MapGet("/search", async (string? status, string? destination, ServerShipmentService svc) =>
    Results.Ok(await svc.SearchShipmentsAsync(status, destination)))
    .RequireAuthorization();

shipmentApi.MapPut("/{id:int}/status", async (int id, ShipmentStatus newStatus, ServerShipmentService svc) =>
{
    await svc.UpdateShipmentStatusAsync(id, newStatus);
    return Results.NoContent();
}).RequireAuthorization();

