 shipmentApi.MapPut("/{id:int}/status", async (int id, ShipmentStatus newStatus, ServerShipmentService svc) =>
 {
     await svc.UpdateShipmentStatusAsync(id, newStatus);
     return Results.NoContent();
 }).RequireAuthorization();

